        "realExample": "¿Cómo superar este lastre? Es necesario entender que la dependencia emocional no es más que la consecuencia de, al menos, dos elementos: Manipulación afectiva por parte del otro. Malinterpretación propia de las emociones ajenas. En el primer escenario, existen consecuencias adicionales. Después de todo, ¿quién regresa de la guerra siendo el mismo individuo? Como es bien sabido, cuando hemos sido controlados afectivamente, desarrollamos problemas de autoestima, de identificación, de autenticidad. Esta es la clave del sufrimiento posterior. ¿Por qué nos cuesta tanto dejar ir a alguien? Está claro que la mente humana, con sus subjetividades, es muy amplia y sería prácticamente imposible reducirla a unas pocas opciones. Sin embargo, a lo largo de mi trayectoria he notado un denominador común bastante reconocible: lo que nos impide cerrar un episodio romántico o emocional pasa por la destrucción casi total de nuestra autoestima. En otras palabras: no nos sentimos capaces de despertar emociones positivas en nadie más porque, en esencia, hemos acaparado para nosotros todas las responsabilidades del hecho. Sea cual fuere tu caso, carece de importancia la forma en que se dieron las cosas. Aquí lo realmente importante es tu bienestar, tu equilibrio emocional y tu crecimiento como ser humano. Llegado un punto, tendrás que desprenderte de todos los posibles factores que desencadenaron en esta situación. Esto implica, a su vez, cuestiones no comprendidas al momento, como la dominación de",
